import 'package:stiv/features/diagnostic/models/hypothesis.dart';

// ─────────────────────────────────────────────────────────────────────────────
// HIPÓTESIS DE CCTV — display_issue, audio_issue (NVR), camera_issue
// ─────────────────────────────────────────────────────────────────────────────

const cctvDisplayHypotheses = <Hypothesis>[
  Hypothesis(id: 'lens_focus', label: 'Problema de enfoque del lente', description: 'El anillo de enfoque del lente está mal calibrado, causando imagen borrosa o fuera de foco. Ocurre después de instalación nueva, vibración o si se manipuló el lente sin bloquearlo después.', recommendedActions: ['Paso 1 — Acceder a la imagen en tiempo real desde el NVR o la interfaz web de la cámara para ver claramente el estado del enfoque.', 'Paso 2 — Localizar el anillo de enfoque en el lente (marcado como FOCUS). Girarlo lentamente en ambas direcciones mientras se observa la imagen.', 'Paso 3 — Si la cámara tiene función de enfoque automático (AF), activarla desde el menú de configuración de imagen del NVR o app del fabricante.', 'Paso 4 — Verificar que el vidrio del domo no esté rayado ni tenga humedad en el interior: la condensación produce efecto de desenfoque que no se puede corregir ajustando el lente.', 'Paso 5 — Si es un lente varifocal motorizado (zoom remote), ajustar también el anillo de zoom (ZOOM) antes de ajustar el enfoque: zoom primero, enfoque después.'], escalationThreshold: 0.25),
  Hypothesis(id: 'dirty_lens', label: 'Lente o domo sucio / con humedad', description: 'El lente o el domo de la cámara está sucio, empañado o con condensación interna. La suciedad en el lente provoca imagen borrosa uniforme; la condensación interna crea manchas o velo en la imagen.', recommendedActions: ['Paso 1 — Limpiar el exterior del domo con un paño de microfibra limpio (seco o ligeramente humedecido con agua destilada). Nunca usar solventes agresivos que puedan rayar el domo.', 'Paso 2 — Si hay empañamiento interno (condensación dentro del domo), abrir el domo y verificar si el sello de silicona está roto o deteriorado.', 'Paso 3 — Revisar si la cámara tiene bolsas desecantes (gel de sílice) internas: si están saturadas (color rosado/azul oscuro), reemplazarlas.', 'Paso 4 — Sellar correctamente el domo con silicona neutra aprobada para electrónica después de la limpieza interna.', 'Paso 5 — En cámaras tipo bullet o PTZ exteriores, limpiar también el parasol (sunshield) para evitar reflexión de luz que cause sobreexposición.'], escalationThreshold: 0.20),
  Hypothesis(id: 'ir_failure', label: 'Falla de LEDs infrarrojos (visión nocturna)', description: 'Los LEDs IR de la cámara no encienden correctamente, causando imagen completamente negra o muy oscura en la noche. Puede ser falla del sensor de luz (fotoresistor) o quemadura de los LEDs IR.', recommendedActions: ['Paso 1 — Cubrir el sensor de luz de la cámara con la mano o un objeto oscuro: si los LEDs IR encienden, el sensor funciona. Si no encienden, hay falla en los LEDs o el circuito IR.', 'Paso 2 — Verificar en el menú de la cámara si el modo IR está en "Auto" o "Manual". Si está en Manual-OFF, cambiarlo a Auto.', 'Paso 3 — Limpiar los LEDs IR con un paño suave y seco: la acumulación de suciedad puede bloquear la emisión infrarroja.', 'Paso 4 — Actualizar el firmware de la cámara: algunos fabricantes corrigen bugs de control IR en actualizaciones de firmware.', 'Paso 5 — Si los LEDs IR están físicamente oscuros o tienen manchas quemadas visibles, el hardware requiere reparación en servicio técnico.'], escalationThreshold: 0.40),
  Hypothesis(id: 'signal_degradation', label: 'Degradación de señal analógica (coaxial)', description: 'En sistemas DVR/analógicos, la señal de video se degrada por cables coaxiales de longitud excesiva, conectores BNC oxidados, o interferencia electromagnética de cables de potencia cercanos.', recommendedActions: ['Paso 1 — Medir la longitud del cable coaxial: RG59 soporta hasta 300m en CVBS, RG6 hasta 400m. Si se supera, instalar un amplificador de señal de video (distribuidor activo).', 'Paso 2 — Inspeccionar los conectores BNC en ambos extremos: desconectar y reconectar para romper oxidación. Si hay corrosión visible, reemplazar el conector BNC.', 'Paso 3 — Verificar que el cable coaxial no esté tendido paralelo a cables de alimentación eléctrica (genera interferencia). Mantener al menos 5cm de separación o usar cable blindado.', 'Paso 4 — Para sistemas HD-CVI/TVI/AHD, verificar que el tipo de cable coaxial sea compatible (RG59 o RG6, no RG58 delgado).', 'Paso 5 — Si hay baluns instalados para video sobre UTP, verificar que sean de la misma marca y calidad en ambos extremos.'], escalationThreshold: 0.35),
  Hypothesis(id: 'nvr_output_failure', label: 'Falla en salida HDMI/VGA del NVR', description: 'El NVR no envía señal de video al monitor. Puede ser el cable HDMI/VGA dañado, la configuración de resolución de salida incompatible, o la salida de video del NVR defectuosa.', recommendedActions: ['Paso 1 — Probar con un cable HDMI o VGA diferente: los cables HDMI de baja calidad pueden fallar sin señal visible de daño.', 'Paso 2 — Conectar el NVR a otro monitor para descartar que el monitor original sea el problema.', 'Paso 3 — Si al encender el NVR el monitor muestra el logo de arranque pero luego se apaga, el problema es la resolución configurada. Mantener presionado el botón de resolución del NVR 5 segundos para resetear a resolución base (1080p/720p).', 'Paso 4 — Verificar en la configuración del NVR (si es accesible remotamente) la resolución y frecuencia de salida: debe coincidir con las especificaciones del monitor.', 'Paso 5 — Si el NVR tiene salida HDMI y VGA simultáneas, probar con ambas para identificar cuál falla.'], escalationThreshold: 0.30),
  Hypothesis(id: 'overexposure_backlight', label: 'Sobreexposición o contraluz excesivo', description: 'La imagen de la cámara aparece muy brillante o con zonas quemadas por exceso de luz. Esto ocurre cuando el punto de instalación tiene una fuente de luz intensa de fondo (ventanas, luces directas).', recommendedActions: ['Paso 1 — Evaluar si la cámara está apuntando directamente a una ventana, bombilla o fuente de luz: reposicionarla o reorientarla si es posible.', 'Paso 2 — Activar la función WDR (Wide Dynamic Range) o BLC (Back Light Compensation) en la configuración de imagen de la cámara.', 'Paso 3 — Ajustar manualmente el nivel de exposición y ganancia en el menú de imagen de la cámara/NVR.', 'Paso 4 — Si la sobreexposición ocurre solo de noche, verificar si los LEDs IR están reflejando en una pared o superficie brillante cercana: alejar la cámara de la pared o reducir la potencia IR.', 'Paso 5 — Para cámaras sin WDR, instalar un parasol o visera adicional para bloquear la fuente de luz problemática.'], escalationThreshold: 0.25),
  Hypothesis(id: 'physical_damage', label: 'Daño físico o golpe severo (Óptica/Sensor dañado)', description: 'La cámara ha recibido un golpe físico por vandalismo, caída, o aves. Esto puede desfasar lentes internos, romper el cristal frontal creando aberraciones (líneas, rayas torcidas) o desplazar el sensor CMOS.', recommendedActions: ['Paso 1 — Observar en físico si la carcasa exterior tiene hundimientos, si el cristal está estrellado, agrietado o apuntando al suelo suelto.', 'Paso 2 — Si la imagen se ve cruzada con grietas fijas oscuras que nunca se mueven, el cristal dome está fisurado ante la lente.', 'Paso 3 — Destapar la carcasa (si es seguro) para ver si el módulo del lente se desprendió de los pines internos del circuito impreso principal.', 'Paso 4 — Las líneas de colores (verdes, moradas) completamente congeladas y ruidosas suelen indicar un golpe que fracturó o desoldó el chip CMOS.', 'Paso 5 — Reemplazar el equipo documentando el siniestro, ya que los daños en placas o celdas CMOS rara vez son rentables de resoldar o cambiar.'], escalationThreshold: 0.20),
  Hypothesis(id: 'sensor_burn_ir_reflection', label: 'Sensor quemado (Láser/Sol) o Reflejo Ciego IR', description: 'Líneas rectas moradas/negras permanentes significan láser/sol que ha quemado de por vida el sensor de imagen. Si falla solo de noche viéndose blanca fantasmal, es el domo ciego reflejando sus propios rayos IR.', recommendedActions: ['Paso 1 — Identidad del daño: Línea vertical / punto negro fijo en todo momento -> Quemadura láser. No reparable, sensor freído.', 'Paso 2 — Identidad de reflejo (Solo nocturno): Al tapar el aro de goma negra (gasket) de la lente del domo interior, la luz IR rebota al cristal.', 'Paso 3 — Desmontar el cristal domo exterior de plástico, limpiarlo interna y externamente. Asegurar que el anillo de espuma del lente toque firmemente el domo contra reflejos perimetrales al tapar.', 'Paso 4 — Remover plásticos y calcomanías de fábrica que nunca se quitaron del lente y que durante meses causan destellos borrosos.', 'Paso 5 — Si no es reflejo de noche, sino falla persistente diurna por quemadura de hardware CMOS, retirar cámara para reciclaje electrónico.'], escalationThreshold: 0.25),
];

const cctvAudioHypotheses = <Hypothesis>[
  Hypothesis(id: 'hdd_failure', label: 'Falla del disco duro (ruido mecánico)', description: 'El disco duro del NVR/DVR está fallando y emite ruidos de clic, rasguño o golpeteo. Estos sonidos indican falla inminente del cabezal o platos del disco. Requiere acción inmediata.', recommendedActions: ['Paso 1 — Acceder al menú de estado del disco en el NVR: buscar la sección "HDD Info" o "Storage" y revisar el estado SMART del disco.', 'Paso 2 — Si el SMART reporta errores de sectores reasignados o de lectura/escritura, el disco está en fase de falla: hacer backup inmediato de las grabaciones críticas.', 'Paso 3 — Apagar el NVR correctamente, esperar 2 minutos y encender: escuchar si el sonido de clic desaparece. Si persiste, el disco tiene daño mecánico.', 'Paso 4 — Reemplazar el disco por uno certificado para videovigilancia (WD Purple, Seagate SkyHawk): estos discos están diseñados para escritura continua 24/7.', 'Paso 5 — Verificar la temperatura del disco en el menú del NVR: debe estar por debajo de 55°C. Si supera esta temperatura, mejorar la ventilación del gabinete.'], escalationThreshold: 0.35),
  Hypothesis(id: 'fan_failure', label: 'Falla o desgaste del ventilador', description: 'El ventilador del NVR, DVR, UPS o switch emite ruido excesivo por desgaste de los rodamientos o por acumulación de polvo que bloquea las aspas.', recommendedActions: ['Paso 1 — Identificar qué equipo emite el ruido apagando o alejando el oído de cada uno por separado.', 'Paso 2 — Con el equipo encendido (cuidado), limpiar las rejillas de ventilación con aire comprimido en spray (latas para electrónica), dirigiendo el aire hacia afuera del equipo.', 'Paso 3 — Apagar el equipo y verificar manualmente que el ventilador gire libremente sin resistencia. Un ventilador trabado genera ruido de motor.', 'Paso 4 — Si el ruido persiste después de la limpieza, el rodamiento del ventilador está desgastado: reemplazar el ventilador por uno del mismo voltaje y dimensiones (ej. 12V DC, 80mm).', 'Paso 5 — Asegurarse de que el equipo tenga espacio de al menos 10cm a los lados y atrás para ventilación adecuada después del reemplazo.'], escalationThreshold: 0.25),
  Hypothesis(id: 'equipment_overheating', label: 'Sobrecalentamiento (ventilador a máxima velocidad)', description: 'El equipo supera su temperatura de operación normal, causando que el ventilador funcione a máxima velocidad generando ruido. Ocurre por ventilación insuficiente, ambiente caliente o polvo obstruyendo las rejillas.', recommendedActions: ['Paso 1 — Verificar la temperatura del cuarto técnico: debe estar entre 18°C y 27°C según ASHRAE. Si está sobre 30°C, el equipo trabajará con el ventilador al máximo permanentemente.', 'Paso 2 — Revisar que el equipo no esté instalado con los laterales tapados: necesita al menos 1U de espacio libre arriba y abajo en el rack.', 'Paso 3 — Limpiar las rejillas de entrada y salida de aire con aire comprimido. En NVR/DVR de escritorio, limpiar también el interior con especial cuidado alrededor del procesador.', 'Paso 4 — Verificar la temperatura interna desde el menú del equipo (si está disponible) y comparar con la temperatura máxima del fabricante (típicamente 40–55°C).', 'Paso 5 — Si el gabinete es cerrado, instalar bandejas de ventilación forzada (rack fan) para extracción de aire caliente por la parte superior.'], escalationThreshold: 0.35),
  Hypothesis(id: 'ground_loop_audio', label: 'Interferencia de bucle a tierra (audio/video)', description: 'Zumbido de 60Hz o líneas de interferencia en pantalla causadas por diferencia de potencial entre equipos conectados a distintos circuitos eléctricos o sin adecuada puesta a tierra.', recommendedActions: ['Paso 1 — Verificar si el zumbido o interferencia desaparece al desconectar el cable de video/audio entre los equipos: si desaparece, es un bucle a tierra.', 'Paso 2 — Conectar todos los equipos del sistema al mismo circuito eléctrico y el mismo punto de tierra cuando sea posible.', 'Paso 3 — Instalar un aislador de bucle a tierra (ground loop isolator) en el cable de video o audio afectado.', 'Paso 4 — Verificar que el UPS tenga conexión a tierra correcta: un UPS sin tierra puede inducir ruido en toda la instalación.', 'Paso 5 — En instalaciones con baluns de video sobre UTP, usar baluns con aislamiento galvánico para eliminar el bucle a tierra.'], escalationThreshold: 0.40),
];

const cctvCameraHypotheses = <Hypothesis>[
  Hypothesis(id: 'stream_config_error', label: 'Error de configuración de stream RTSP/ONVIF', description: 'El protocolo de video, puerto, credenciales o resolución del stream son incorrectos. Ocurre frecuentemente al agregar cámaras de terceros a un NVR de diferente fabricante.', recommendedActions: ['Paso 1 — Acceder a la interfaz web de la cámara directamente con su IP (en navegador: http://IP_CAMARA) y verificar el stream RTSP configurado (ruta, puerto, usuario y contraseña).', 'Paso 2 — En el NVR, al agregar la cámara manualmente verificar: protocolo (ONVIF/RTSP), IP, puerto (usualmente 554 para RTSP u 80/8000 para ONVIF), usuario y contraseña correctos.', 'Paso 3 — Probar el stream con VLC Player: ir a "Abrir de red" y escribir rtsp://usuario:contraseña@IP_CAMARA:554/stream1 para confirmar que el stream funciona fuera del NVR.', 'Paso 4 — Restablecer la configuración de stream de la cámara a valores por defecto desde su interfaz web y reconfigurar.', 'Paso 5 — Verificar la compatibilidad ONVIF: algunos dispositivos requieren habilitar ONVIF explícitamente en la configuración de "Servicios de red" de la cámara.'], escalationThreshold: 0.35),
  Hypothesis(id: 'storage_full', label: 'Almacenamiento lleno o disco dañado en NVR', description: 'El disco del NVR está lleno (sin grabación en bucle) o tiene sectores defectuosos que impiden la escritura. La cámara puede verse en vivo pero no grabar.', recommendedActions: ['Paso 1 — Acceder al menú de almacenamiento del NVR: verificar el porcentaje de uso del disco. Si está al 100%, habilitar sobrescritura (overwrite/loop recording) en la configuración.', 'Paso 2 — Revisar el estado SMART del disco en el NVR: ir a "Mantenimiento > HDD Info" y verificar que el estado sea "Normal".', 'Paso 3 — Formatear el disco desde el menú del NVR si el estado SMART reporta errores corregibles (no en caso de errores críticos).', 'Paso 4 — Verificar que las cámaras tengan programación de grabación correcta: si el horario de grabación está deshabilitado o mal configurado, el NVR no grabará aunque el disco esté libre.', 'Paso 5 — Si el disco tiene errores graves, reemplazarlo y formatear el nuevo desde el menú del NVR antes de asignar cámaras.'], escalationThreshold: 0.30),
  Hypothesis(id: 'hdd_sata_fault', label: 'Falla del Bus SATA / Cableado interno del DVR', description: 'El DVR arroja pitos de alarma de disco duro pero el disco duro se ha probado y está sano. La verdadera causa es el cable de datos planito (SATA) interno o su línea de poder desoldada por vibraciones.', recommendedActions: ['Paso 1 — Retirar los tornillos de la tapa del NVR/DVR. Ubicar el cable SATA plano (usualmente rojo o negro) que va de PCB al HDD.', 'Paso 2 — Retirarlo y limpiar conectores. Muchos cables SATA de fábrica fallan a los meses por torsión. Reemplazarlo por un cable tipo clip.', 'Paso 3 — Extraer también el conector cuadradito de cables de colores (molex-SATA de alimentación) y volverlo a clavar firme en el disco duro.', 'Paso 4 — Si la placa NVR tiene doble puerto SATA, probar mudando el disco duro e ingresando un nuevo cable al puerto secundario.', 'Paso 5 — Si tras colocar cables nuevos, conectores firmes, el DVR sigue "No Detectando Storage/0MB", la controladora sur de la placa base murió y requiere reemplazar hardware NVR.'], escalationThreshold: 0.25),
  Hypothesis(id: 'camera_not_discovered', label: 'Cámara IP no descubierta por el NVR', description: 'El NVR no detecta la cámara IP en el escaneo de red automático. Puede ser por diferente segmento de red, ONVIF deshabilitado, o credenciales por defecto cambiadas.', recommendedActions: ['Paso 1 — Verificar que la cámara está en el mismo segmento de red que el NVR: ambos deben tener IPs del mismo rango (ej. NVR: 192.168.1.100, Cámara: 192.168.1.101).', 'Paso 2 — Usar la herramienta de búsqueda de IPs del fabricante (ej. SADP para Hikvision, IP Finder para Dahua) para localizar la cámara y ajustar su IP si es necesario.', 'Paso 3 — Agregar la cámara manualmente en el NVR: ingresar IP, protocolo, puerto, usuario y contraseña directamente.', 'Paso 4 — Verificar que el servicio ONVIF esté habilitado en la cámara (menú de Servicios de red en la interfaz web de la cámara).', 'Paso 5 — Si la cámara fue reseteada de fábrica, las credenciales por defecto suelen ser admin/admin o admin/12345: actualizar las credenciales después de agregarla al NVR.'], escalationThreshold: 0.30),
  Hypothesis(id: 'firmware_bug', label: 'Bug de firmware / malfunction por software', description: 'La cámara o el NVR tiene un comportamiento anómalo causado por un bug en la versión de firmware instalada. Se manifiesta con cierres inesperados, pérdida de configuración o funciones que no responden.', recommendedActions: ['Paso 1 — Realizar un reinicio del equipo desde el menú de administración (no desconectar la energía abruptamente): ir a "Mantenimiento > Reiniciar".', 'Paso 2 — Consultar el sitio web del fabricante y verificar si existe una actualización de firmware disponible para el modelo exacto.', 'Paso 3 — Descargar el firmware oficial y actualizarlo desde el menú "Mantenimiento > Actualización de firmware". NUNCA usar firmware de un modelo diferente aunque sea de la misma marca.', 'Paso 4 — Si el problema persiste después de la actualización, realizar un restablecimiento de fábrica y reconfigurar el equipo.', 'Paso 5 — Documentar el comportamiento anómalo (fecha, hora, descripción) y reportar al soporte técnico del fabricante si el bug persiste en la última versión de firmware.'], escalationThreshold: 0.40),
  Hypothesis(id: 'ptz_config_error', label: 'Error de configuración PTZ / RS-485', description: 'El control PTZ no funciona porque el protocolo, la dirección o la velocidad de baudios del bus RS-485 no coinciden entre la cámara y el DVR.', recommendedActions: ['Paso 1 — Verificar en la cámara PTZ (etiqueta o menú DIP switches) el protocolo configurado: Pelco-D, Pelco-P, ONVIF u otro.', 'Paso 2 — En el DVR, ir a configuración de PTZ del canal correspondiente y asegurarse de que el protocolo, la dirección (ID) y la velocidad de baudios (9600 para Pelco-D por defecto) coincidan exactamente.', 'Paso 3 — Verificar el cableado RS-485: los terminales A(+) y B(-) deben estar correctamente conectados en ambos extremos. Un cable invertido evita el control PTZ.', 'Paso 4 — Si hay múltiples cámaras PTZ en el bus RS-485, verificar que cada una tenga una dirección única (1, 2, 3, etc.) y que haya resistencia de terminación de 120Ω en el último dispositivo.', 'Paso 5 — Para PTZ IP (ONVIF), asegurarse de que la cámara esté agregada correctamente en el NVR con sus credenciales.'], escalationThreshold: 0.40),
  Hypothesis(id: 'camera_power_failure', label: 'Falla de alimentación eléctrica de la cámara', description: 'La cámara no recibe alimentación eléctrica adecuada: PoE insuficiente, adaptador DC defectuoso o cable de alimentación con falla.', recommendedActions: ['Paso 1 — Verificar el LED de encendido de la cámara: si no enciende ningún LED, la cámara no está recibiendo energía.', 'Paso 2 — Probar con otro puerto PoE del switch o con un inyector PoE independiente para descartar el puerto del switch.', 'Paso 3 — Si la cámara usa adaptador DC, medir el voltaje de salida del adaptador con multímetro: debe coincidir ±5% con el voltaje indicado en la etiqueta.', 'Paso 4 — Verificar que el estándar PoE del switch sea compatible con la cámara (revisarlo en las especificaciones del modelo).', 'Paso 5 — Revisar el cable UTP para PoE: si el par de alimentación tiene continuidad pero alta resistencia, la caída de voltaje puede ser insuficiente para la cámara en cables largos.'], escalationThreshold: 0.30),
  Hypothesis(id: 'camera_mount_loose', label: 'Basculamiento o Base floja (Vibración/Movimiento Roto)', description: 'A través de la cámara domo o PTZ se ve que la imagen pierde foco sistemáticamente o se desencaja por culpa de las vibraciones del tránsito, viento u obras contiguas, dando el falso síntoma de PTZ Roto a software.', recommendedActions: ['Paso 1 — Ir al mástil o brazo de soporte exterior de la cámara para ejercer apalancamiento suave. ¿Tiembla o suena metal?', 'Paso 2 — Muchos problemas de motorización "PTZ" donde no sigue recorridos ocurre por base desajustada soltando la corona de plástico que alinea el eje.', 'Paso 3 — Desmontar el collarín, reapretar chazos u anclajes plásticos con pernos, poner arandelas de resorte.', 'Paso 4 — En cámaras LPR (Lectura placa de auto) es letal. Reubicar mástil a un suelo libre de vibraciones vehiculares pesadas.', 'Paso 5 — Solo tras asegurar su fijación pétrea, usar el menú de la interfaz "PTZ Calibration" / Restablecer topes mecánicos.'], escalationThreshold: 0.20),
  // ── Nuevas hipótesis de cámara ─────────────────────────────────────────────
  Hypothesis(id: 'nvr_ip_config_error', label: 'IP del NVR o cámara mal configurada / fuera de segmento', description: 'La cámara o el NVR tiene una dirección IP que no pertenece al segmento de red correcto, impidiendo la comunicación. Ocurre tras cambios de router, resets de fábrica o migración de red.', recommendedActions: ['Paso 1 — Conectar un PC directamente La cámara con un cable cruzado (o al mismo switch) y usar la herramienta del fabricante (SADP, IP Finder, ConfigTool) para encontrar la IP actual de la cámara.', 'Paso 2 — Cambiar la IP de la cámara para que pertenezca al mismo segmento que el NVR (ej. si el NVR es 192.168.1.100, la cámara debe ser 192.168.1.X).', 'Paso 3 — En el NVR, ir a "Gestión de dispositivos > Agregar cámara" y buscar o agregar manualmente con la nueva IP.', 'Paso 4 — Verificar que la máscara de subred sea idéntica en la cámara y el NVR (generalmente 255.255.255.0).', 'Paso 5 — Si el NVR tiene un switch PoE integrado, asegurarse de que el puerto LAN del NVR esté en el mismo rango que su switch interno.'], escalationThreshold: 0.25),
  Hypothesis(id: 'onvif_auth_failure', label: 'Fallo de autenticación ONVIF (credenciales incorrectas)', description: 'El NVR puede ver la cámara en la red pero no logra agregarla porque las credenciales ONVIF son incorrectas o la cuenta ONVIF fue desactivada en el equipo.', recommendedActions: ['Paso 1 — Acceder a la interfaz web de la cámara (http://IP_CAMARA) e ir a "Configuración > Red > Servicios avanzados > ONVIF": verificar que ONVIF esté habilitado.', 'Paso 2 — Crear o restablecer el usuario ONVIF: en algunos fabricantes (ZKTeco, Hikvision) el usuario ONVIF es distinto del usuario de la interfaz web.', 'Paso 3 — En el NVR, al agregar la cámara en modo ONVIF, usar exactamente el usuario y contraseña del perfil ONVIF (no del admin de la cámara).', 'Paso 4 — Si la cámara fue reseteada, las credenciales ONVIF vuelven a los valores de fábrica: admin/admin o admin/12345.', 'Paso 5 — Verificar que la fecha y hora del NVR y la cámara estén sincronizadas: una diferencia mayor a 5 minutos puede causar fallo de autenticación en algunos protocolos.'], escalationThreshold: 0.30),
  Hypothesis(id: 'recording_schedule_disabled', label: 'Programación de grabación deshabilitada o incorrecta', description: 'La cámara se ve en vivo correctamente pero no existen grabaciones porque el horario de grabación del canal está desactivado, solo en movimiento sin actividad, o el plan fue borrado por un reinicio.', recommendedActions: ['Paso 1 — En el NVR ir a "Configuración > Almacenamiento > Programación de grabación" y verificar que el canal de la cámara tenga habilitados los días y franjas horarias deseadas.', 'Paso 2 — Revisar el tipo de grabación configurado: "Continua" graba siempre; "Movimiento" solo graba con detección de movimiento. Verificar que la sensibilidad del movimiento no sea cero.', 'Paso 3 — Verificar que el disco duro del NVR tenga espacio disponible y que la opción "Sobrescritura" (Loop Recording) esté habilitada.', 'Paso 4 — Revisar si el HDD está asignado al canal: en algunos NVR, si hay múltiples discos, cada canal debe tener un disco asignado explícitamente.', 'Paso 5 — Aplicar el mismo plan de grabación a todos los canales usando la opción "Copiar a todos los canales" en la interfaz de programación.'], escalationThreshold: 0.20),
  Hypothesis(id: 'bandwidth_congestion', label: 'Congestión de ancho de banda / Red saturada', description: 'La red no tiene capacidad suficiente para transmitir el video de múltiples cámaras simultáneamente, causando cortes, congelamiento o video de baja calidad. Ocurre con muchas cámaras de alta resolución en una red de 100Mbps.', recommendedActions: ['Paso 1 — Calcular el ancho de banda requerido: multiplicar el bitrate de cada cámara (ej. 4Mbps para 4MP) por el número de cámaras. Un switch de 100Mbps soporta máximo 10 cámaras a 4Mbps.', 'Paso 2 — Reducir el bitrate de las cámaras más alejadas o de menor importancia: bajar de 4Mbps a 2Mbps en H.265 mantiene buena calidad con la mitad del ancho de banda.', 'Paso 3 — Verificar si el switch es Fast Ethernet (100Mbps) o Gigabit (1Gbps): reemplazar switches de 100Mbps por Gigabit para instalaciones con más de 8 cámaras.', 'Paso 4 — Habilitar H.265 (HEVC) en las cámaras que lo soporten: reduce el ancho de banda a la mitad con la misma calidad visual que H.264.', 'Paso 5 — Separar el tráfico de videovigilancia en una VLAN dedicada para evitar que otro tráfico de la red compita con el video.'], escalationThreshold: 0.35),
];
